```javascript
const fs = require('fs');

const values = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const [budget, ...bills] = values;

bills.sort((a, b) => a - b);

let count = 0;
for (const bill of bills) {
  if (budget >= bill) {
    budget -= bill;
    count++;
  } else {
    break;
  }
}

console.log(count);
